<script setup lang="ts">import {Heart,Plus,Star} from 'lucide-vue-next';import type {Product} from '../data';import {money} from '../data';import {useShopStore} from '../stores/shop';defineProps<{product:Product}>();const store=useShopStore();</script><template><article class="product-card"><div class="product-image"><RouterLink :to="`/product/${product.id}`"><img :src="product.image" :alt="product.name"></RouterLink><span v-if="product.tags[0]" class="tag">{{product.tags[0]}}</span><button class="wish" :class="{active:store.wishlist.includes(product.id)}" @click="store.toggleWish(product.id)"><Heart :size="18" :fill="store.wishlist.includes(product.id)?'currentColor':'none'"/></button></div><div class="product-info"><div class="rating"><Star :size="14" fill="currentColor"/> {{product.rating}} <span>({{product.reviews}})</span></div><RouterLink :to="`/product/${product.id}`"><h3>{{product.name}}</h3></RouterLink><p class="arabic">{{product.nameAr}}</p><div class="product-bottom"><strong>{{money(product.price)}}</strong><button class="add" @click="store.add(product)"><Plus :size="17"/> Add</button></div></div></article></template>
